  "cop.subtitle": "ਤੁਹਾਡੇ ਲਾਈਵ ਅੰਕੜਿਆਂ ਉੱਤੇ ਇੱਕ ਸਹਾਇਕ ਪਰਤ - ਰੋਜ਼ਾਨਾ ਸੰਖੇਪ, ਸਿਫ਼ਾਰਸ਼ ਕੀਤੇ ਕਦਮ ਅਤੇ ਸਾਧਾਰਨ ਭਾਸ਼ਾ ਵਿੱਚ ਜਵਾਬ, ਸਭ ਤੁਹਾਡੇ ਆਪਣੇ ਡੇਟੇ ਤੋਂ ਗਿਣੇ ਗਏ।",
  "cop.assistiveLead": "ਕੋਪਾਇਲਟ ਹੈ",
