  "cop.assistiveRest": "ਹਰ ਸੁਝਾਅ ਤੁਹਾਡੇ ਲਾਈਵ ਡੇਟੇ ਦੀ ਨਿਯਮ-ਆਧਾਰਿਤ ਪੜ੍ਹਤ ਹੈ ਅਤੇ ਹਰ \"ਕਾਰਵਾਈ\" ਇੱਕ ਪ੍ਰੀਵਿਊ ਹੈ ਜੋ ਤੁਹਾਨੂੰ ਸਹੀ ਪੰਨੇ ਨਾਲ ਜੋੜਦੀ ਹੈ - ਕੁਝ ਵੀ ਆਪਣੇ ਆਪ ਪੈਸਾ ਨਹੀਂ ਹਿਲਾਉਂਦਾ ਜਾਂ ਕੁਝ ਫ਼ਾਈਲ ਨਹੀਂ ਕਰਦਾ।",
