  "cop.cardHealth": "ਸਿਹਤ ਸਕੋਰ",
  "cop.cardHealthSub": "ਸੰਯੁਕਤ ਵਿੱਤੀ ਸਿਹਤ",
  "cop.whatHeading": "ਕੋਪਾਇਲਟ ਕੀ ਕਰਦਾ ਹੈ",
  "cop.whatDesc": "ਇਸ ਨੂੰ ਇੱਕ ਵਿੱਤੀ ਵਿਸ਼ਲੇਸ਼ਕ ਸਮਝੋ ਜਿਸ ਨੇ ਤੁਹਾਡੇ ਵਰਕਸਪੇਸ ਦਾ ਹਰ ਅੰਕੜਾ ਪੜ੍ਹਿਆ ਹੈ। ਇਹ ਸੰਖੇਪ ਕਰਦਾ, ਦਰਜਾ ਦਿੰਦਾ ਅਤੇ ਜਵਾਬ ਦਿੰਦਾ ਹੈ - ਫਿਰ ਤੁਹਾਨੂੰ ਉਸ ਪੰਨੇ 'ਤੇ ਭੇਜਦਾ ਹੈ ਜੋ ਅਸਲ ਕੰਮ ਕਰਦਾ ਹੈ।",
  "cop.featBriefDesc": "ਨਕਦੀ, ਰਨਵੇ, ਬਕਾਇਆ ਤੇ ਅੱਜ ਦੇਯ ਦਾ ਇੱਕ-ਸਕਰੀਨ ਸੰਖੇਪ।",
  "cop.featActionsDesc": "ਨਕਦੀ ਪ੍ਰਭਾਵ ਅਨੁਸਾਰ ਦਰਜਾਬੰਦ ਹਿਊਰਿਸਟਿਕ ਅਗਲੇ-ਵਧੀਆ-ਕਦਮ, ਹਰ ਇੱਕ ਸਹੀ ਟੂਲ ਨਾਲ ਡੀਪ-ਲਿੰਕ ਕੀਤਾ।",
  "cop.featLauncherDesc": "ਜੋ ਤੁਸੀਂ ਚਾਹੁੰਦੇ ਹੋ ਟਾਈਪ ਕਰੋ ('ਬਕਾਇਆ ਵਸੂਲੋ', 'ਪੂਰਵ-ਅਨੁਮਾਨ') ਅਤੇ ਸਿੱਧੇ ਓਥੇ ਪਹੁੰਚੋ।",
  "cop.featQaDesc": "'ਨਕਦੀ ਕਿਉਂ ਘਟੀ?' ਵਰਗੇ ਸਵਾਲਾਂ ਦੇ ਸਾਧਾਰਨ ਭਾਸ਼ਾ ਵਿੱਚ ਜਵਾਬ, ਸਿਰਫ਼ ਤੁਹਾਡੇ ਮੈਟ੍ਰਿਕਸ 'ਤੇ ਆਧਾਰਿਤ।",
  "cop.featGoalDesc": "ਇੱਕ ਰਨਵੇ ਟੀਚਾ ਤੈਅ ਕਰੋ; ਯੋਜਨਾਕਾਰ ਵਸੂਲਣ / ਕੱਟਣ / ਉਧਾਰ ਲੈਣ ਦਾ ਮਿਸ਼ਰਣ ਸੁਝਾਉਂਦਾ ਹੈ।",
  "cop.featAttentionDesc": "ਤੁਹਾਡੇ ਡੇਟੇ ਤੋਂ ਸਾਹਮਣੇ ਆਈਆਂ ਵਿਸੰਗਤੀਆਂ ਤੇ ਖ਼ਤਰੇ, ਨਵੀਨਤਮ ਪਹਿਲਾਂ।",
  "cop.jumpHeading": "ਸਬੰਧਿਤ ਮਾਡਿਊਲ 'ਤੇ ਜਾਓ",
  "cop.autoComputed": "ਆਪਣੇ-ਆਪ ਗਿਣਿਆ",
  "cop.briefDesc": "ਅੱਜ ਮਾਇਨਾ ਰੱਖਣ ਵਾਲੇ ਅੰਕੜਿਆਂ ਦਾ ਸਾਧਾਰਨ-ਭਾਸ਼ਾ ਸੰਖੇਪ। ਤੁਹਾਡਾ ਡੇਟਾ ਬਦਲਦੇ ਹੀ ਆਪਣੇ ਆਪ ਤਾਜ਼ਾ ਹੁੰਦਾ ਹੈ।",
  "cop.openFullBrief": "ਪੂਰਾ CFO ਬ੍ਰੀਫ਼ ਖੋਲ੍ਹੋ",
  "cop.briefCopied": "ਬ੍ਰੀਫ਼ ਕਲਿੱਪਬੋਰਡ 'ਤੇ ਕਾਪੀ ਹੋਇਆ",
  "cop.copyBrief": "ਬ੍ਰੀਫ਼ ਕਾਪੀ ਕਰੋ",
  "cop.actionsDesc": "ਜ਼ਰੂਰੀਅਤ ਤੇ ਨਕਦੀ ਪ੍ਰਭਾਵ ਅਨੁਸਾਰ ਦਰਜਾਬੰਦ ਹਿਊਰਿਸਟਿਕ ਅਗਲੇ-ਵਧੀਆ-ਕਦਮ। ਕਿਸੇ 'ਤੇ ਕਾਰਵਾਈ ਕਰਨ ਨਾਲ ਉਹ ਪੰਨਾ ਖੁੱਲ੍ਹਦਾ ਹੈ ਜੋ ਅਸਲ ਵਿੱਚ ਇਹ ਕਰਦਾ ਹੈ - ਕੋਪਾਇਲਟ ਕਦੇ ਖ਼ੁਦ ਅਮਲ ਨਹੀਂ ਕਰਦਾ।",
  "cop.potentialImpact": "ਸੰਭਾਵੀ ਨਕਦੀ ਪ੍ਰਭਾਵ:",
  "cop.restore": "ਬਹਾਲ ਕਰੋ",
  "cop.markHandled": "ਨਿਪਟਾਇਆ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਕਰੋ",
  "cop.launcherDesc": "ਜੋ ਤੁਸੀਂ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ ਸਾਧਾਰਨ ਸ਼ਬਦਾਂ ਵਿੱਚ ਟਾਈਪ ਕਰੋ - ਲਾਂਚਰ ਕੀਵਰਡ ਮਿਲਾਉਂਦਾ ਹੈ ਅਤੇ ਸਿੱਧੇ ਸਹੀ ਮਾਡਿਊਲ 'ਤੇ ਲੈ ਜਾਂਦਾ ਹੈ। ਇਹ ਸਿਰਫ਼ ਨੈਵੀਗੇਟ ਕਰਦਾ ਹੈ; ਕੰਮ ਤੁਹਾਡੇ ਲਈ ਨਹੀਂ ਕਰਦਾ।",
  "cop.launcherPlaceholder": "ਜਿਵੇਂ ਬਕਾਇਆ ਵਸੂਲੋ, ਵ੍ਹਾਟ-ਇਫ਼ ਚਲਾਓ, GST ਫ਼ਾਈਲ ਕਰੋ…",
  "cop.launcherNoMatch": "ਕੋਈ ਮਿਲਦੀ ਕਾਰਵਾਈ ਨਹੀਂ। “ਵਸੂਲੋ”, “ਪੂਰਵ-ਅਨੁਮਾਨ”, “ਖ਼ਰਚ” ਜਾਂ “ਟੈਕਸ” ਵਰਗੇ ਸ਼ਬਦ ਵਰਤੋ।",
  "cop.qaDescLead": "ਸਾਧਾਰਨ ਭਾਸ਼ਾ ਵਿੱਚ ਕੁਝ ਵੀ ਪੁੱਛੋ। AI ਤਰਕ ਕਰਦਾ ਹੈ",
  "cop.qaDescBold": "ਸਿਰਫ਼ ਤੁਹਾਡੇ ਲਾਈਵ ਵਿੱਤੀ ਸਨੈਪਸ਼ੌਟ 'ਤੇ",
  "cop.qaDescRest": "- ਨਕਦੀ, ਰਨਵੇ, ਪ੍ਰਾਪਤੀਆਂ, ਕਰਜ਼ਾ ਤੇ ਸਿਹਤ। ਜੇ AI ਉਪਲਬਧ ਨਾ ਹੋਵੇ, ਤੁਹਾਨੂੰ ਉਹਨਾਂ ਹੀ ਅੰਕੜਿਆਂ ਤੋਂ ਤੁਰੰਤ ਆਫ਼ਲਾਈਨ ਜਵਾਬ ਮਿਲੇਗਾ।",
  "cop.qaPlaceholder": "ਆਪਣੇ ਵਿੱਤ ਬਾਰੇ ਪੁੱਛੋ…",
  "cop.thinking": "ਸੋਚ ਰਿਹਾ ਹੈ…",
  "cop.ask": "ਪੁੱਛੋ",
  "cop.qaReasoning": "ਤੁਹਾਡੇ ਲਾਈਵ ਅੰਕੜਿਆਂ 'ਤੇ ਤਰਕ ਕਰ ਰਿਹਾ ਹੈ…",
  "cop.offlineNote": "ਆਫ਼ਲਾਈਨ ਜਵਾਬ - AI ਬਿਨਾਂ ਤੁਹਾਡੇ ਮੈਟ੍ਰਿਕਸ ਤੋਂ ਗਿਣਿਆ।",
  "cop.aiNotConfigured": "AI ਸੰਰਚਿਤ ਨਹੀਂ - ਆਫ਼ਲਾਈਨ ਜਵਾਬ ਵਰਤ ਰਿਹਾ ਹੈ",
