  "cop.risksDesc": "ਹੁਣ ਤੁਹਾਡੀ ਵਿੱਤੀ ਸਿਹਤ 'ਤੇ ਸਭ ਤੋਂ ਵੱਧ ਬੋਝ ਪਾਉਣ ਵਾਲੇ ਤਿੰਨ ਮੁੱਦੇ, ਦਰਜਾਬੰਦ ਕਿ ਇਹ ਤੁਹਾਡੇ ਸਕੋਰ ਤੇ ਨਕਦੀ ਨੂੰ ਕਿੰਨਾ ਮਹਿੰਗੇ ਪੈਂਦੇ ਹਨ। ਇੱਕ ਧਿਆਨ-ਕੇਂਦਰਿਤ ਸਹਾਇਤਾ - ਕਾਰਵਾਈ ਤੋਂ ਪਹਿਲਾਂ ਸਮੀਖਿਆ ਕਰੋ।",
