  "cop.risksEmptyBody": "ਹਰ ਸਿਹਤ ਚਾਲਕ 60 ਤੋਂ ਉੱਪਰ ਸਕੋਰ ਕਰ ਰਿਹਾ ਹੈ ਅਤੇ ਕੋਈ ਗੰਭੀਰ ਸੰਕੇਤ ਨਹੀਂ ਚੱਲ ਰਿਹਾ।",
  "cop.savingsDesc": "ਪਿਛਲੇ 90 ਦਿਨਾਂ ਵਿੱਚ ਵਾਰ-ਵਾਰ ਦੁਹਰਾਏ ਗਏ ਖ਼ਰਚੇ, ਮਾਸਿਕ ਲਾਗਤ ਅਨੁਸਾਰ ਦਰਜਾਬੰਦ - ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਤੇ ਦੁਹਰੇ ਖ਼ਰਚੇ ਲੱਭਣ ਦੀ ਆਮ ਥਾਂ। ਜੋ ਕੱਟੋਗੇ ਟਿੱਕ ਕਰੋ ਬੱਚਤ ਗਿਣਨ ਲਈ; ਇਹ ਕੁਝ ਵੀ ਰੱਦ ਨਹੀਂ ਕਰਦਾ।",
  "cop.earmarkedToCut": "ਕੱਟਣ ਲਈ ਨਿਸ਼ਾਨਬੱਧ:",
  "cop.savingsEmptyTitle": "₹5,000/ਮਹੀਨਾ ਤੋਂ ਵੱਧ ਕੋਈ ਦੁਹਰਾਇਆ ਖ਼ਰਚ ਨਹੀਂ ਮਿਲਿਆ",
  "cop.savingsEmptyBody": "ਜਾਂ ਤਾਂ ਖ਼ਰਚ ਚੰਗੀ ਤਰ੍ਹਾਂ ਫੈਲਿਆ ਹੈ ਜਾਂ ਹਾਲੇ ਲੇਬਲ ਵਾਲਾ ਕਾਫ਼ੀ ਇਤਿਹਾਸ ਨਹੀਂ।",
  "cop.reviewFullSpend": "ਪੂਰਾ ਖ਼ਰਚ ਸਮੀਖਿਆ ਕਰੋ",
  "cop.kpiRunway": "ਰਨਵੇ (ਮਹੀਨੇ)",
  "cop.kpiMargin": "ਕੁੱਲ ਮਾਰਜਿਨ (%)",
  "cop.kpiDso": "DSO (ਦਿਨ)",
  "cop.kpiHealth": "ਸਿਹਤ ਸਕੋਰ",
  "cop.targetsDesc": "ਹਰ ਮੁੱਖ KPI ਲਈ ਇੱਕ ਟੀਚਾ ਤੈਅ ਕਰੋ; ਟ੍ਰੈਕਰ ਇਸ ਨੂੰ ਲਾਈਵ ਮੁੱਲ ਨਾਲ ਤੁਲਨਾ ਕਰਦਾ ਹੈ ਅਤੇ ਪਾੜ 'ਤੇ ਤੁਹਾਨੂੰ ਪ੍ਰੇਰਦਾ ਹੈ। ਟੀਚੇ ਤੁਹਾਡੇ ਵਰਕਸਪੇਸ ਨਾਲ ਸੰਭਾਲੇ ਜਾਂਦੇ ਹਨ - ਅਸਲ ਮੁੱਲ ਸਿੱਧੇ ਤੁਹਾਡੇ ਡੇਟੇ ਤੋਂ ਪੜ੍ਹੇ ਜਾਂਦੇ ਹਨ।",
