  "cop.eodDesc": "ਕਾਪੀ-ਲਈ-ਤਿਆਰ ਸਾਰ ਕਿ ਕਾਰੋਬਾਰ ਕਿੱਥੇ ਖੜ੍ਹਾ ਹੈ, ਅੱਜ ਕੀ ਹਿੱਲਿਆ ਤੇ ਕੀ ਹਾਲੇ ਖੁੱਲ੍ਹਾ ਹੈ - ਇਸ ਨੂੰ ਸਟੈਂਡਅੱਪ, WhatsApp ਅੱਪਡੇਟ ਜਾਂ ਆਪਣੇ ਮੀਟਿੰਗ ਨੋਟਸ ਵਿੱਚ ਪੇਸਟ ਕਰੋ। ਤੁਹਾਡੇ ਲਾਈਵ ਅੰਕੜਿਆਂ ਤੋਂ ਬਣਿਆ।",
  "cop.cashWatchDesc": "ਤੁਹਾਡੀ ਬੰਦ ਹੋਣ ਵਾਲੀ ਨਕਦੀ ਦਾ 8-ਹਫ਼ਤਾ ਅਨੁਮਾਨ - ਸ਼ੁਰੂਆਤੀ ਬਕਾਇਆ ਨਾਲ ਸੰਚਾਲਨ ਰਨ-ਰੇਟ, ਸੰਭਾਵਿਤ ਵਸੂਲੀਆਂ ਤੇ ਮਿਤੀਬੱਧ ਦੇਣਦਾਰੀਆਂ। ਇਹ ਚਿਤਾਵਨੀ ਦਿੰਦਾ ਹੈ ਜਦੋਂ ਨਕਦੀ ~2-ਹਫ਼ਤੇ ਦੇ ਖ਼ਰਚ ਬਫ਼ਰ ਤੋਂ ਹੇਠਾਂ ਡਿੱਗੇ। ਇੱਕ ਪ੍ਰੀਵਿਊ, ਗਾਰੰਟੀ ਨਹੀਂ; ਇੱਥੇ ਕੁਝ ਵੀ ਪੈਸਾ ਨਹੀਂ ਹਿਲਾਉਂਦਾ।",
