  "cop.collectDesc": "ਵਸੂਲੀ ਤਰਜੀਹ ਅਨੁਸਾਰ ਦਰਜਾਬੰਦ ਤੁਹਾਡੀਆਂ ਖੁੱਲ੍ਹੀਆਂ ਇਨਵਾਇਸਾਂ - ਵੱਡੇ ਬਕਾਏ ਤੇ ਸਭ ਤੋਂ ਲੰਬੇ-ਬਕਾਇਆ ਉੱਪਰ ਆਉਂਦੇ ਹਨ, ਤਾਂ ਜੋ ਸਵੇਰ ਭਰ ਪਿੱਛਾ ਕਰਨ ਨਾਲ ਸਭ ਤੋਂ ਵੱਧ ਨਕਦੀ ਵਸੂਲ ਹੋਵੇ। ਜਿਵੇਂ ਕੰਮ ਕਰਦੇ ਹੋ ਟਿੱਕ ਕਰੋ; ਕੋਪਾਇਲਟ ਕਦੇ ਤੁਹਾਡੇ ਲਈ ਕਿਸੇ ਨਾਲ ਸੰਪਰਕ ਨਹੀਂ ਕਰਦਾ।",
