  "voi.capAudioStmtTitle": "ਆਡੀਓ ਸਟੇਟਮੈਂਟਾਂ",
  "voi.capAudioStmtBody": "ਬੋਲਿਆ ਵਿੱਤੀ ਸੰਖੇਪ ਬਣਾਓ ਤੇ ਵਾਪਸ ਚਲਾਓ।",
  "voi.overviewHeading": "ਆਵਾਜ਼-ਪਹਿਲ ਵਿੱਤ, ਇਮਾਨਦਾਰੀ ਨਾਲ ਸੀਮਤ",
  "voi.overviewBody": "ਇੱਥੇ ਹਰ ਚੀਜ਼ ਅੱਜ, ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਕੰਮ ਕਰਦੀ ਹੈ - ਕਿਸੇ ਕਲਾਊਡ ਸਪੀਚ ਸੇਵਾ ਦੀ ਲੋੜ ਨਹੀਂ। ਹਰ ਟੂਲ ਹੇਠਲੀ API ਦੀ ਪਛਾਣ ਕਰਦਾ ਹੈ ਤੇ ਉਪਲਬਧ ਨਾ ਹੋਣ 'ਤੇ ਟਾਈਪਿੰਗ 'ਤੇ ਵਾਪਸ ਆ ਜਾਂਦਾ ਹੈ।",
  "voi.badgeAvailable": "ਉਪਲਬਧ",
  "voi.badgeFallbackOnly": "ਸਿਰਫ਼ ਫੌਲਬੈਕ",
  "voi.overviewFallback": "ਆਵਾਜ਼ ਦੀ ਗੁਣਵੱਤਾ ਪੂਰੀ ਤਰ੍ਹਾਂ ਤੁਹਾਡੇ ਡਿਵਾਈਸ ਤੇ ਬ੍ਰਾਊਜ਼ਰ 'ਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ। Web Speech ਪਛਾਣ ਡੈਸਕਟਾਪ 'ਤੇ Chrome/Edge ਤੇ Android WebView ਵਿੱਚ ਸਭ ਤੋਂ ਵਧੀਆ ਕੰਮ ਕਰਦੀ ਹੈ; Safari/iOS ਸਹਾਇਤਾ ਅਧੂਰੀ ਹੈ। ਲਹਿਜੇ ਤੇ ਦੇਸੀ ਭਾਸ਼ਾ ਦੀ ਸ਼ੁੱਧਤਾ ਇੰਸਟਾਲ ਕੀਤੇ OS ਸਪੀਚ ਇੰਜਣ ਅਨੁਸਾਰ ਵੱਖ ਹੁੰਦੀ ਹੈ - ਜਦੋਂ ਪਛਾਣ ਉਪਲਬਧ ਨਾ ਹੋਵੇ, ਇੱਥੇ ਹਰ ਟੂਲ ਟਾਈਪ ਕੀਤਾ ਇਨਪੁੱਟ ਸਵੀਕਾਰ ਕਰਦਾ ਹੈ।",
  "voi.captureHeading": "ਆਵਾਜ਼ ਨੋਟ → ਲੈਣ-ਦੇਣ ਡਰਾਫਟ",
  "voi.captureFallback": "ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਮਾਈਕ੍ਰੋਫ਼ੋਨ ਡਿਕਟੇਸ਼ਨ ਉਪਲਬਧ ਨਹੀਂ ਹੈ। ਹੇਠਲੇ ਬਾਕਸ ਵਿੱਚ ਲਾਈਨ ਟਾਈਪ ਕਰੋ - ਪਾਰਸਿੰਗ ਬਿਲਕੁਲ ਉਸੇ ਤਰ੍ਹਾਂ ਕੰਮ ਕਰਦੀ ਹੈ।",
