  "voi.whatsappSubtitle": "ਆਪਣੀ ਭਾਸ਼ਾ ਵਿੱਚ ਇੱਕ ਸੁਨੇਹਾ ਬੋਲੋ, ਫਿਰ ਇਸਨੂੰ ਪਹਿਲਾਂ ਤੋਂ ਭਰਿਆ WhatsApp ਨੂੰ ਸਿੱਧਾ ਸੌਂਪੋ। ਅਸੀਂ WhatsApp ਦਾ ਸ਼ੇਅਰ ਲਿੰਕ ਖੋਲ੍ਹਦੇ ਹਾਂ - ਤੁਹਾਡਾ ਨਾ-ਭੇਜਿਆ ਡਰਾਫਟ, ਤੁਹਾਡਾ ਨੰਬਰ - ਤਾਂ ਜੋ ਤੁਸੀਂ ਖ਼ੁਦ ਭੇਜੋ ਟੈਪ ਕਰੋ। ਪਿਛੋਕੜ ਵਿੱਚ ਕੋਈ ਸੁਨੇਹਾ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।",
