  "tok.subtitle": "RBI e-rupee ਅਤੇ GIFT-City ਰੇਲਾਂ ਲਈ ਪ੍ਰੋਗਰਾਮੇਬਲ-ਪੇਮੈਂਟ ਨਿਯਮ, ਏਸਕ੍ਰੋ ਅਤੇ ਟੋਕਨਾਈਜ਼ਡ ਸੰਪਤੀਆਂ ਡਿਜ਼ਾਈਨ ਕਰੋ - ਉਹਨਾਂ ਦੇ ਲਾਈਵ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ।",
  "tok.honestNote": "ਅੱਜ ਡਿਜ਼ਾਈਨ ਅਤੇ ਸਿਮੂਲੇਟ ਕਰੋ; ਸੈਟਲਮੈਂਟ ਉਦੋਂ ਸਰਗਰਮ ਹੋਵੇਗੀ ਜਦੋਂ CBDC / ਟੋਕਨਾਈਜ਼ੇਸ਼ਨ ਰੇਲਾਂ ਲਾਈਵ ਹੋਣਗੀਆਂ। ਇੱਥੇ ਸਭ ਕੁਝ ਅਸਲੀ ਸਪੈਕਸ, ਸਪਲਿਟ ਅਤੇ ਬੈਲੇਂਸ ਲੋਕਲੀ ਕੰਪਿਊਟ ਕਰਦਾ ਹੈ - ਕੋਈ ਲਾਈਵ ਬਲਾਕਚੇਨ ਜਾਂ e-rupee ਨੈੱਟਵਰਕ ਕਾਲ ਨਹੀਂ ਹੈ।",
