  "tok.ruleDesc": "ਇੱਕ ਸ਼ਰਤੀ-ਭੁਗਤਾਨ ਨਿਯਮ ਬਣਾਓ। ਇਸ ਨੂੰ ਪਹਿਲਾਂ ਭਰਨ ਲਈ ਇੱਕ ਅਸਲੀ ਬਕਾਇਆ ਇਨਵੌਇਸ ਚੁਣੋ, ਜਾਂ ਇੱਕ ਅਸਲੀ ਧਿਰ - ਇਹ ਇੱਕ ਸਾਦੀ-ਭਾਸ਼ਾ ਵਾਲਾ ਬਿਆਨ ਅਤੇ ਇੱਕ ਕਾਪੀ-ਯੋਗ JSON ਸਪੈਕ ਦਿੰਦਾ ਹੈ ਜੋ ਰੇਲ ਦੇ ਲਾਈਵ ਹੋਣ 'ਤੇ ਤੁਸੀਂ ਦੇ ਸਕਦੇ ਹੋ।",
