  "front.whatForBody": "Headroom ਦਾ ਰੋਡਮੈਪ ਅਜਿਹੇ ਵਿੱਤ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦਾ ਹੈ ਜੋ ਪਲ ਵਿੱਚ ਮਹਿਸੂਸ, ਫ਼ੈਸਲਾ ਅਤੇ ਸੈਟਲ ਕਰਦਾ ਹੈ - ਅਤੇ ਕੱਲ੍ਹ ਦੇ ਕੁਆਂਟਮ ਕੰਪਿਊਟਰਾਂ ਖ਼ਿਲਾਫ਼ ਸੁਰੱਖਿਅਤ ਰਹਿੰਦਾ ਹੈ। ਇਸ ਵਿੱਚੋਂ ਕੁਝ ਅੱਜ ਦੇ ਡੇਟਾ 'ਤੇ ਬਣਾਉਣ ਯੋਗ ਹੈ ਅਤੇ ਇੱਥੇ ਕੰਮ ਕਰਦੇ ਟੂਲ ਵਜੋਂ ਭੇਜਿਆ ਗਿਆ ਹੈ। ਬਾਕੀ ਰੇਲਾਂ (RTP, ਪ੍ਰੋਗਰਾਮੇਬਲ CBDC, ਸਟ੍ਰੀਮਿੰਗ ਪੇਰੋਲ) 'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ ਜੋ ਅਜੇ ਵੀ ਪਰਿਪੱਕ ਹੋ ਰਹੀਆਂ ਹਨ - ਉਹ ਈਮਾਨਦਾਰ, ਇੰਟਰਐਕਟਿਵ ਪੂਰਵਦਰਸ਼ਨ ਵਜੋਂ ਦਿਖਾਈ ਦਿੰਦੀਆਂ ਹਨ ਤਾਂ ਜੋ ਤੁਸੀਂ ਲਾਈਵ ਪੈਸੇ ਦੀ ਹਿਲਜੁਲ ਨੂੰ ਨਕਲੀ ਬਣਾਏ ਬਿਨਾਂ ਡਿਜ਼ਾਈਨ ਨੂੰ ਆਕਾਰ ਦੇ ਸਕੋ।",
