  "front.alertsFootnote": "ਨਿਯਮ ਹੁਣ ਸਟੋਰ ਹੁੰਦੇ ਹਨ ਅਤੇ Ambient Rules ਇੰਜਣ ਦੁਆਰਾ ਮੁਲਾਂਕਣ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। WhatsApp/ਈਮੇਲ ਡਿਲੀਵਰੀ ਉਦੋਂ ਸਰਗਰਮ ਹੁੰਦੀ ਹੈ ਜਦੋਂ ਉਹ ਚੈਨਲ ਤੁਹਾਡੇ ਟੈਨੈਂਟ ਲਈ ਜੁੜਦੇ ਹਨ।",
  "front.ambientHeading": "ਬੈਕਗ੍ਰਾਊਂਡ ਵਾਚ ਨਿਯਮ",
  "front.ambientBlurb": "\"ਜੇ <ਮੈਟ੍ਰਿਕ> <ਓਪ> <ਮੁੱਲ> ਤਾਂ <ਕਾਰਵਾਈ>\" ਨਿਯਮ ਸਰਗਰਮ ਕਰੋ। ਇਹ ਹੇਠਾਂ ਤੁਹਾਡੇ ਮੌਜੂਦਾ ਵਿੱਤ ਖ਼ਿਲਾਫ਼ ਲਾਈਵ ਮੁਲਾਂਕਣ ਕਰਦੇ ਹਨ - ਬੈਚ ਜੌਬ ਦੀ ਉਡੀਕ ਨਹੀਂ।",
