  "front.supercomputeHeading": "ਸਿਨੇਰੀਓ ਸੁਪਰਕੰਪਿਊਟ (Monte-Carlo)",
  "front.supercomputeBlurb": "ਤੁਹਾਡੀਆਂ ਆਮਦਨ/ਲਾਗਤ ਧਾਰਨਾਵਾਂ 'ਤੇ ਹਜ਼ਾਰਾਂ ਬੇਤਰਤੀਬ ਭਵਿੱਖ ਚਲਾਉਂਦਾ ਹੈ ਤਾਂ ਜੋ ਪਤਾ ਲੱਗੇ ਕਿ ਨਕਦੀ ਕਿੱਥੇ ਪਹੁੰਚਦੀ ਹੈ। ਤੁਹਾਡੀ ਲਾਈਵ ਨਕਦੀ ਸਥਿਤੀ ਨਾਲ ਪਹਿਲਾਂ ਭਰਿਆ।",
