  "front.p10": "P10 (ਨਿਰਾਸ਼ਾਵਾਦੀ)",
  "front.p50": "P50 (ਮੱਧਮਾਨ)",
  "front.p90": "P90 (ਆਸ਼ਾਵਾਦੀ)",
  "front.chanceNeg": "ਨੈਗੇਟਿਵ ਨਕਦੀ ਦੀ ਸੰਭਾਵਨਾ",
  "front.supercomputeFootnote": "ਹਰ ਰਨ ਤੁਹਾਡੀਆਂ ਧਾਰਨਾਵਾਂ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਇੱਕ ਸਧਾਰਨ ਵੰਡ ਤੋਂ ਮਾਸਿਕ ਆਮਦਨ ਅਤੇ ਲਾਗਤ ਖਿੱਚਦਾ ਹੈ। ਵੱਧ ਰਨ ਗਿਣਤੀ ਕੰਪਿਊਟ ਸਮੇਂ ਦੀ ਕੀਮਤ 'ਤੇ ਵਧੇਰੇ ਸੁਚੱਜੇ ਪਰਸੈਂਟਾਈਲ ਦਿੰਦੀ ਹੈ। ਸੰਕੇਤਕ ਯੋਜਨਾਬੰਦੀ ਟੂਲ, ਗਾਰੰਟੀ ਨਹੀਂ।",
  "front.quantumHeading": "ਪੋਸਟ-ਕੁਆਂਟਮ ਮਾਈਗ੍ਰੇਸ਼ਨ ਤਿਆਰੀ",
  "front.quantumBlurb": "ਆਪਣੇ ਵਿੱਤ ਸਟੈਕ ਨੂੰ ਕੁਆਂਟਮ ਡੀਕ੍ਰਿਪਸ਼ਨ ਖ਼ਿਲਾਫ਼ ਸੁਰੱਖਿਅਤ ਬਣਾਉਣ ਦੇ ਕਦਮ ਟ੍ਰੈਕ ਕਰੋ। ਪ੍ਰਗਤੀ ਸੇਵ ਹੁੰਦੀ ਹੈ।",
  "front.bandReady": "ਕੁਆਂਟਮ-ਤਿਆਰ",
  "front.bandMigration": "ਮਾਈਗ੍ਰੇਸ਼ਨ ਵਿੱਚ",
  "front.bandExposed": "ਖੁੱਲ੍ਹਾ",
  "front.readinessScore": "ਤਿਆਰੀ ਸਕੋਰ",
  "front.stepsComplete": "{done}/{total} ਕਦਮ ਪੂਰੇ",
  "front.quantumFootnote": "NIST PQC ਮਾਰਗਦਰਸ਼ਨ (Kyber/Dilithium/SPHINCS+) 'ਤੇ ਆਧਾਰਿਤ। \"Harvest-now-decrypt-later\" ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਅੱਜ ਚੋਰੀ ਕੀਤਾ ਡੇਟਾ ਕੁਆਂਟਮ ਕੰਪਿਊਟਰਾਂ ਦੇ ਪਰਿਪੱਕ ਹੋਣ 'ਤੇ ਡੀਕ੍ਰਿਪਟ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ - ਲੰਬੇ ਸਮੇਂ ਦੇ ਵਿੱਤੀ ਰਿਕਾਰਡ ਤਰਜੀਹ ਹਨ।",
  "front.eventsHeading": "ਲਾਈਵ ਇਵੈਂਟ ਸਟ੍ਰੀਮ",
  "front.eventsBlurb": "ਤੁਹਾਡੇ ਸਟੋਰ ਵਿੱਚ ਹਾਲੀਆ ਬਦਲਾਅ, ਇੱਕ \"ਇਵੈਂਟ ਬੱਸ\" ਫੀਡ ਵਜੋਂ ਪੇਸ਼ - ਇਵੈਂਟ-ਸੰਚਾਲਿਤ ਵਿੱਤ ਦਾ ਪੂਰਵਦਰਸ਼ਨ।",
  "front.eventsEmpty": "ਅਜੇ ਕੋਈ ਇਵੈਂਟ ਨਹੀਂ। ਲੈਣ-ਦੇਣ ਜਾਂ ਇਨਵੌਇਸ ਸ਼ਾਮਲ ਕਰੋ ਅਤੇ ਉਹ ਇੱਥੇ ਸਟ੍ਰੀਮ ਹੋਣਗੇ।",
  "front.radarHeading": "ਟੈੱਕ-ਤਿਆਰੀ ਰਡਾਰ",
  "front.radarBlurb": "ਦਰਜਾ ਦਿਓ ਕਿ ਤੁਹਾਡਾ ਵਿੱਤ ਸੰਚਾਲਨ ਅੱਜ ਚਾਰ ਖੇਤਰਾਂ ਵਿੱਚ ਕਿੱਥੇ ਖੜ੍ਹਾ ਹੈ (0 = ਸ਼ੁਰੂ ਨਹੀਂ, 5 = ਮੋਹਰੀ)। ਤੁਹਾਡੇ ਖਾਤੇ ਵਿੱਚ ਸੇਵ ਹੁੰਦਾ ਹੈ।",
  "front.radarOverall": "ਸਮੁੱਚੀ ਫਰੰਟੀਅਰ ਤਿਆਰੀ",
  "front.radarFootnote": "ਤੁਹਾਡੇ ਰੋਡਮੈਪ ਨੂੰ ਕੇਂਦ੍ਰਿਤ ਕਰਨ ਲਈ ਇੱਕ ਸਵੈ-ਮੁਲਾਂਕਣ - ਸਭ ਤੋਂ ਹੇਠਲੀ ਧੁਰੀ ਆਮ ਤੌਰ 'ਤੇ ਅਗਲਾ ਸਭ ਤੋਂ ਵਧੀਆ ਨਿਵੇਸ਼ ਹੁੰਦੀ ਹੈ। Headroom ਹਰੇਕ ਖ਼ਿਲਾਫ਼ ਟੂਲ ਭੇਜਦਾ ਹੈ ਜਿਵੇਂ ਹੀ ਉਹ ਭਾਰਤੀ ਰੇਲਾਂ 'ਤੇ ਬਣਾਉਣ ਯੋਗ ਬਣਦੇ ਹਨ।",
  "front.rtpTitle": "Request-to-Pay ਡਿਜ਼ਾਈਨਰ",
  "front.rtpBlurb": "ਉਹ ਢਾਂਚਾਗਤ RTP ਆਬਜੈਕਟ ਡਿਜ਼ਾਈਨ ਕਰੋ ਜੋ ਇੱਕ ਵਿਕਰੇਤਾ ਨੂੰ ਮਿਲੇਗਾ ਜਦੋਂ ਕਾਰੋਬਾਰਾਂ ਲਈ UPI Request-to-Pay ਰੇਲਾਂ ਪਰਿਪੱਕ ਹੋਣਗੀਆਂ। ਇਹ ਇੱਕ ਪੂਰਵਦਰਸ਼ਨ ਪੇਲੋਡ ਬਣਾਉਂਦਾ ਹੈ - ਇਹ ਅਜੇ ਅਸਲੀ ਭੁਗਤਾਨ ਬੇਨਤੀ ਨਹੀਂ ਭੇਜਦਾ।",
  "front.rtpCompose": "ਬੇਨਤੀ ਬਣਾਓ",
  "front.rtpPayloadPreview": "RTP ਪੇਲੋਡ ਪੂਰਵਦਰਸ਼ਨ",
  "front.streamingTitle": "ਸਟ੍ਰੀਮਿੰਗ-ਪੇਰੋਲ ਸਿਮੂਲੇਟਰ",
  "front.streamingBlurb": "ਮਾਸਿਕ ਦੀ ਬਜਾਏ ਪ੍ਰਤੀ ਸਕਿੰਟ ਇਕੱਠੀ ਹੋ ਰਹੀ ਤਨਖਾਹ ਦਾ ਮਾਡਲ ਬਣਾਓ। ਸਿਰਫ਼ ਦ੍ਰਿਸ਼ਟਾਂਤਕ ਗਣਿਤ - ਅਸਲੀ ਲਗਾਤਾਰ ਭੁਗਤਾਨ ਲਈ ਸਟ੍ਰੀਮਿੰਗ ਰੇਲਾਂ ਦੀ ਲੋੜ ਹੈ ਅਤੇ ਇਹ ਤੁਹਾਡੀ ਪੇਰੋਲ ਨਾਲ ਜੁੜਿਆ ਨਹੀਂ।",
  "front.treasuryTitle": "ਖੁਦਮੁਖਤਿਆਰ-ਖਜ਼ਾਨਾ ਨੀਤੀ",
  "front.treasuryBlurb": "ਉਹ ਹੱਦਾਂ ਪਰਿਭਾਸ਼ਿਤ ਕਰੋ ਜਿਨ੍ਹਾਂ ਦਾ ਇੱਕ ਸਵੈ-ਚੱਲਦਾ ਖਜ਼ਾਨਾ ਏਜੰਟ ਪਾਲਣ ਕਰੇਗਾ - ਘੱਟੋ-ਘੱਟ ਬਫ਼ਰ, ਸਵੀਪ ਹੱਦਾਂ, ਯੀਲਡ ਫ਼ਰਸ਼। ਤੁਹਾਡੀ ਇੱਛਤ ਨੀਤੀ ਵਜੋਂ ਸੇਵ; ਖੁਦਮੁਖਤਿਆਰ ਖਜ਼ਾਨਾ ਯੋਗ ਹੋਣ ਤੱਕ ਕੋਈ ਫੰਡ ਨਹੀਂ ਹਿੱਲਦਾ।",
  "front.m2mTitle": "ਮਸ਼ੀਨ-ਤੋਂ-ਮਸ਼ੀਨ ਭੁਗਤਾਨ ਸੰਕਲਪ",
  "front.m2mBlurb": "ਇੱਕ IoT ਡਿਵਾਈਸ ਦਾ ਮਾਡਲ ਬਣਾਓ ਜੋ ਹਰ ਯੂਨਿਟ ਦੀ ਵਰਤੋਂ ਲਈ ਭੁਗਤਾਨ ਕਰਦਾ ਹੈ (ਜਿਵੇਂ ਇੱਕ EV ਪ੍ਰਤੀ km ਸੈਟਲ ਕਰਦਾ ਹੈ, ਇੱਕ ਮੀਟਰ ਪ੍ਰਤੀ kWh) ਪ੍ਰੋਗਰਾਮੇਬਲ ਪੈਸੇ 'ਤੇ। ਸੰਕਲਪਿਕ ਕੈਲਕੁਲੇਟਰ - ਕੋਈ ਡਿਵਾਈਸ ਜਾਂ CBDC ਰੇਲ ਜੁੜੀ ਨਹੀਂ।",
